    db.execute('CREATE TABLE prices (id REAL PRIMARY KEY, label TEXT)');
    db.execute("INSERT INTO prices (id, label) VALUES (1.5, 'a'), (2.5, 'b')");
    db.close();

    final found = await tool.execute(
      {'path': 'real.db:prices:1.5'},
      null,
      null,
