  http.Client releaseClient({List<int>? archiveBytes}) =>
      MockClient((request) async {
        if (request.url.path.endsWith('/releases/latest')) {
          return http.Response(
            '',
            302,
            headers: {
              'location':
                  'https://github.com/IstiN/flutter_agent_harness/'
