    final result = await tool.execute(
      {'path': 'huge.db?q=SELECT * FROM t'},
      null,
      null,
    );
    final text = _text(result);
    expect(
      text,
      contains(
        '[Output capped at 1000 rows; add a LIMIT/OFFSET clause to the '
