    test('the ffi resolver failure shape is recognized', () {
      expect(isSqliteDynamicLibraryLoadFailure(_macMissingDylibError), isTrue);
      expect(
        isSqliteDynamicLibraryLoadFailure(_linuxMissingDylibError),
