    '-----BEGIN PUBLIC KEY-----\n'
    '[REDACTED:High Entropy String]/EXT7Sa\n'
    '/lkqlJUA1chgVeOv3HAPMfOZR5203eS8ObjYEI38WtJHTV8hGYqCHBzv7iJHz1+b\n'
    '[REDACTED:High Entropy String]/3w6nv7jl\n'
